package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.GetMemberLoansUseCase;
import com.example.lending.application.port.in.GetMemberLoansUseCase.GetMemberLoansQuery;
import com.example.lending.application.port.in.GetMemberLoansUseCase.MemberLoansPage;
import com.example.lending.application.port.in.GetMemberUseCase;
import com.example.lending.application.port.in.RegisterMemberUseCase;
import com.example.lending.application.port.in.RegisterMemberUseCase.RegisterMemberCommand;
import com.example.lending.domain.Member;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.UUID;

@RestController
@RequestMapping("/members")
public class MemberController {

    private final RegisterMemberUseCase registerMemberUseCase;
    private final GetMemberUseCase getMemberUseCase;
    private final GetMemberLoansUseCase getMemberLoansUseCase;

    public MemberController(RegisterMemberUseCase registerMemberUseCase, GetMemberUseCase getMemberUseCase,
                            GetMemberLoansUseCase getMemberLoansUseCase) {
        this.registerMemberUseCase = registerMemberUseCase;
        this.getMemberUseCase = getMemberUseCase;
        this.getMemberLoansUseCase = getMemberLoansUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public MemberResponse registerMember(@RequestBody RegisterMemberRequest request) {
        Member member = registerMemberUseCase.registerMember(new RegisterMemberCommand(request.memberId(), request.name()));
        return MemberResponse.from(member);
    }

    @GetMapping("/{memberId}")
    public MemberResponse getMember(@PathVariable UUID memberId) {
        return MemberResponse.from(getMemberUseCase.getMember(memberId));
    }

    // 반납하지 않은 대출만 대출일 순으로 준다
    @GetMapping("/{memberId}/loans")
    public MemberLoansResponse getActiveLoans(@PathVariable UUID memberId,
                                              @RequestParam(defaultValue = "0") int page,
                                              @RequestParam(defaultValue = "20") int size) {
        MemberLoansPage result = getMemberLoansUseCase.getActiveLoans(new GetMemberLoansQuery(memberId, page, size));
        return MemberLoansResponse.from(result);
    }
}
package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.GetMemberLoansUseCase.ActiveLoan;
import com.example.lending.application.port.in.GetMemberLoansUseCase.MemberLoansPage;

import java.time.LocalDate;
import java.util.List;
import java.util.UUID;

public record MemberLoansResponse(List<LoanItemResponse> items, int page, int size, long totalCount) {

    static MemberLoansResponse from(MemberLoansPage result) {
        List<LoanItemResponse> items = result.items().stream()
                .map(LoanItemResponse::from)
                .toList();
        return new MemberLoansResponse(items, result.page(), result.size(), result.totalCount());
    }

    public record LoanItemResponse(UUID loanId, UUID bookId, String title, LocalDate loanedAt, LocalDate dueAt) {

        static LoanItemResponse from(ActiveLoan loan) {
            return new LoanItemResponse(loan.loanId(), loan.bookId(), loan.title(), loan.loanedAt(), loan.dueAt());
        }
    }
}
package com.example.lending.application.port.in;

import java.time.LocalDate;
import java.util.List;
import java.util.UUID;

public interface GetMemberLoansUseCase {

    MemberLoansPage getActiveLoans(GetMemberLoansQuery query);

    // page 는 0부터 시작하고, size 는 1 이상 MAX_SIZE 이하여야 한다
    record GetMemberLoansQuery(UUID memberId, int page, int size) {

        public static final int MAX_SIZE = 100;

        public GetMemberLoansQuery {
            if (memberId == null) {
                throw new IllegalArgumentException("memberId is required");
            }
            if (page < 0) {
                throw new IllegalArgumentException("page must not be negative");
            }
            if (size < 1 || size > MAX_SIZE) {
                throw new IllegalArgumentException("size must be between 1 and " + MAX_SIZE);
            }
        }
    }

    // totalCount 는 페이지와 상관없이 반납되지 않은 대출 전체 건수다
    record MemberLoansPage(List<ActiveLoan> items, int page, int size, long totalCount) {
    }

    record ActiveLoan(UUID loanId, UUID bookId, String title, LocalDate loanedAt, LocalDate dueAt) {
    }
}
package com.example.lending.application.service;

import com.example.lending.application.port.in.GetMemberLoansUseCase;
import com.example.lending.application.port.out.CountActiveLoansPort;
import com.example.lending.application.port.out.LoadActiveLoansPort;
import com.example.lending.application.port.out.LoadActiveLoansPort.ActiveLoanRow;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@Transactional(readOnly = true)
public class GetMemberLoansService implements GetMemberLoansUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadActiveLoansPort loadActiveLoansPort;
    private final CountActiveLoansPort countActiveLoansPort;

    public GetMemberLoansService(LoadMemberPort loadMemberPort,
                                 LoadActiveLoansPort loadActiveLoansPort,
                                 CountActiveLoansPort countActiveLoansPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadActiveLoansPort = loadActiveLoansPort;
        this.countActiveLoansPort = countActiveLoansPort;
    }

    @Override
    public MemberLoansPage getActiveLoans(GetMemberLoansQuery query) {
        loadMemberPort.loadMember(query.memberId())
                .orElseThrow(() -> new MemberNotFoundException(query.memberId()));

        List<ActiveLoan> items = loadActiveLoansPort.loadActiveLoans(query.memberId(), query.page(), query.size())
                .stream()
                .map(row -> new ActiveLoan(row.loanId(), row.bookId(), row.title(), row.loanedAt(), row.dueAt()))
                .toList();
        long totalCount = countActiveLoansPort.countActiveLoans(query.memberId());
        return new MemberLoansPage(items, query.page(), query.size(), totalCount);
    }
}
